 {visible.map(group=>{const playingGroup=group.cueIds.some(id=>activeCueIds.has(id));const groupTransportActive=!!mediaFile&&playback.currentMs>=group.start&&playback.currentMs<group.end;const revealDeleted=showDeleted||(originalPreview&&playingGroup);const palette=colorFor(group.canonicalSpeaker);const ambiguous=isCompound(group.canonicalSpeaker)||group.isMultiVoice||!group.canonicalSpeaker;const groupIndex=groupIndices.get(group.id)??-1;return <Fragment key={group.id}>{renderFilterGap(filterContext.before.get(group.id))}<article className={`message-row${playingGroup?" is-playing":""}`} data-group-id={group.id} style={{"--speaker-color":palette.color,"--speaker-bg":palette.bg,"--bubble-bg":palette.bubble} as CSSProperties}><div className="avatar" aria-hidden="true">{ambiguous?<Users size={17}/>:group.speaker?(/^話者\s*\d+/.test(group.speaker)?group.speaker.match(/\d+/)?.[0]:[...group.speaker][0]):"?"}</div><div className="message-content"><div className="message-meta"><span className="speaker-label"><Highlight text={group.speaker??"話者不明"} query={query}/></span>{showTimes&&<button className="message-time time-seek" {...middleSeek(group.start)} title={`${formatTime(group.start,true)} → ${formatTime(group.end,true)} / クリックで再生`} onClick={()=>seek(group.start)}>{formatTime(group.start)}<span>–</span>{formatTime(group.end)}</button>}{group.sourceCount>1&&<span className="merged-count"><Link2 size={11}/>{group.sourceCount}字幕</span>}{group.manual&&<span className="ambiguous-badge">話者を調整</span>}{group.cues.some(cue=>"estimatedTiming" in cue&&cue.estimatedTiming)&&<span className="precision-badge estimated">話者の区切りは推定</span>}{mediaFile&&<div className="utterance-playback"><button className={groupTransportActive&&playback.playing&&playback.mode==="original"?"active":""} aria-label={`${formatTime(group.start,true)}の発言を削除前で再生`} aria-pressed={groupTransportActive&&playback.playing&&playback.mode==="original"} title="この発言から元メディアを連続再生" disabled={mediaExportBusy} onClick={()=>playUtterance(group.start,group.end,"original")}>{groupTransportActive&&playback.playing&&playback.mode==="original"?<Pause size={12}/>:<Play size={12}/>}削除前</button><button className={`edited${groupTransportActive&&playback.playing&&playback.mode==="edited"?" active":""}`} aria-label={`${formatTime(group.start,true)}の発言を削除後で再生`} aria-pressed={groupTransportActive&&playback.playing&&playback.mode==="edited"} title="この発言からカット区間をスキップして連続再生" disabled={mediaExportBusy} onClick={()=>playUtterance(group.start,group.end,"edited")}>{groupTransportActive&&playback.playing&&playback.mode==="edited"?<Pause size={12}/>:<Scissors size={12}/>}削除後</button></div>}</div>
 {ambiguous&&<div className="message-controls"><span className="ambiguous-badge">{group.canonicalSpeaker?"複数の話者候補":"話者を確認"}</span><button className="merge-neighbor" disabled={group.deleted||!canMergeInView||groupIndex===0||groups[groupIndex-1]?.deleted} title={!canMergeInView?"検索と話者フィルターを解除すると結合できます":`上の「${groups[groupIndex-1]?.speaker??"話者不明"}」に合わせて結合`} onClick={()=>{apply(s=>mergeWithNeighbor(doc,s,group.id,"up",mergeOptions));notify("上の発言に話者を合わせて結合しました。時刻は保持しています。",true);}}><ArrowUp size={13}/>上と結合</button><button className="merge-neighbor" disabled={group.deleted||!canMergeInView||groupIndex===groups.length-1||groups[groupIndex+1]?.deleted} title={!canMergeInView?"検索と話者フィルターを解除すると結合できます":`下の「${groups[groupIndex+1]?.speaker??"話者不明"}」に合わせて結合`} onClick={()=>{apply(s=>mergeWithNeighbor(doc,s,group.id,"down",mergeOptions));notify("下の発言に話者を合わせて結合しました。時刻は保持しています。",true);}}><ArrowDown size={13}/>下と結合</button></div>}
 <div className="message-bubble">{group.lines.map(line=>{const lineRemoved=line.tokens.filter(t=>t.text.trim()).every(t=>deletedTokens.has(t.id));if(lineRemoved&&!revealDeleted)return null;return <Fragment key={line.id}>{gapByCue.get(line.cueId)&&doc.linesByCue.get(line.cueId)?.[0]?.id===line.id&&<GapRow gap={gapByCue.get(line.cueId)!} verdict={visualResults[gapByCue.get(line.cueId)!.id]} onOpen={()=>{const g=gapByCue.get(line.cueId)!;openReview({...g,label:'字幕なし・無音未確認',kind:'gap'});}}/>}<div className={`source-line${selectedLines.has(line.id)?" selected":""}${lineRemoved?" removed":""}${activeLineIds.has(line.id)?" is-playing":""}`} key={line.id} data-line-id={line.id}><label className="line-select" title="この行を選択"><input type="checkbox" checked={selectedLines.has(line.id)} disabled={lineRemoved} aria-label={`${formatTime(line.start,true)}の行を選択`} onChange={e=>setSelectedLines(current=>{const next=new Set(current);if(e.target.checked)next.add(line.id);else next.delete(line.id);return next;})}/></label>{showTimes&&<button className="line-time" {...middleSeek(line.start)} onClick={()=>seek(line.start)} title={`${formatTime(line.start,true)}–${formatTime(line.end,true)} / ${PRECISION_LABEL[line.precision]}`}>{formatTime(line.start).replace(/^00:/,"")}</button>}<div className="line-content message-text">{!mounted?line.text:line.tokens.map(token=><TranscriptToken key={token.id} token={token} spans={deletedSpans.get(token.cueId)??NO_SPANS} showDeleted={revealDeleted} active={activeTokenIds.has(token.id)} playbackMode={playback.mode} interactionMode={interactionMode} canPlay={!!mediaFile&&!mediaExportBusy} onSeek={seek} query={query} shouldIgnoreClick={shouldIgnoreClick} onRestore={restoreText} onDelete={deleteToken}/>)}</div><button className="line-edit-button" aria-label={`${formatTime(line.start,true)}の字幕を修正`} title="この字幕の誤字を修正" onClick={()=>openCorrection([line.cueId])}><Pencil size={13}/></button><button className="line-delete-button" aria-label={`${formatTime(line.start,true)}の行を削除`} title="この元字幕行を削除" disabled={lineRemoved} onClick={()=>{apply(s=>deleteLines(doc,s,[line.id]));notify("行を削除し、カット時刻を記録しました",true);}}><Trash2 size={13}/></button></div></Fragment>;})}</div>
 <div className="message-actions"><button className="button secondary small" aria-label={`${formatTime(group.start,true)}の発言の映像・時間軸`} onClick={()=>openReview({start:group.start,end:group.end,label:'発話の映像・時間軸',kind:'speech'})}>映像・時間軸</button><button className="message-edit-button" aria-label={`${formatTime(group.start,true)}の発言の誤字を修正`} onClick={()=>openCorrection(group.cueIds)}><Pencil size={12}/>誤字を修正</button><button className="copy-message" aria-label={`${formatTime(group.start)}の発言をコピー`} onClick={()=>{navigator.clipboard.writeText(`${group.speaker??"話者不明"}：${group.text}`).then(()=>notify("発言をコピーしました")).catch(()=>notify("本文を選択してコピーしてください"));}}><Copy size={12}/>コピー</button></div></div></article></Fragment>;})}
